mapper.delete:
delete from MST_CREDIT_MARKET_INFO
   where SECID = #{secid,jdbcType=VARCHAR}
     and CDATE = #{cdate,jdbcType=VARCHAR}
     and VALUE_SOURCE = #{valueSource,jdbcType=VARCHAR}

mapper.select:
SELECT m.SECID secid, f.FINPROD_ABBR finprodAbbr, m.VALUE_SOURCE, sdl1.item_value valueSourceStr, m.CDATE cdate, m.MDPRICE mdprice, m.MCPRICE mcprice, m.MINT mint, m.MYIELD*100 myield, m.M_MDURATION mMduration, m.M_CNVXTY mCnvxty, m.ISSUE_MARKET_NUM issueMarketNum, m.CREDIT_TYPE creditType, sdl2.item_value creditTypeStr FROM MST_CREDIT_MARKET_INFO m LEFT JOIN FIN_PRODUCT f ON f.FINPROD_MARKET_ID=m.SECID LEFT JOIN INTERF_CREDITINFO i ON i.SECID = m.SECID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='VALUATION_SOURCE' and sdl1.item_code = m.VALUE_SOURCE LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='PROTECTION_CREDIT_TYPE' and sdl2.item_code = m.CREDIT_TYPE
AND (m.SECID IN
#{item}
)
AND m.VALUE_SOURCE = #{valueSource}
AND m.cdate >= #{cdateStart,jdbcType=VARCHAR}
AND m.cdate <= #{cdateEnd,jdbcType=VARCHAR}
ORDER BY m.SECID

SELECT m.SECID secid, f.FINPROD_ABBR finprodAbbr, m.VALUE_SOURCE valueSource, sdl1.item_value valueSourceStr, m.CDATE cdate, m.MDPRICE mdprice, m.MCPRICE mcprice, m.MINT mint, m.MYIELD*100 myield, m.M_MDURATION mMduration, m.M_CNVXTY mCnvxty, m.ISSUE_MARKET_NUM issueMarketNum, m.CREDIT_TYPE creditType, sdl2.item_value creditTypeStr FROM MST_CREDIT_MARKET_INFO m LEFT JOIN FIN_PRODUCT f ON f.FINPROD_MARKET_ID=m.SECID LEFT JOIN INTERF_CREDITINFO i ON i.SECID = m.SECID LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='VALUATION_SOURCE' and sdl1.item_code = m.VALUE_SOURCE LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='PROTECTION_CREDIT_TYPE' and sdl2.item_code = m.CREDIT_TYPE
AND (m.SECID IN
#{item}
)
AND m.VALUE_SOURCE = #{valueSource}
AND m.cdate >= TO_DATE(#{cdateStart},'YYYY-MM-DD')
AND m.cdate <= TO_DATE(#{cdateEnd},'YYYY-MM-DD')
ORDER BY m.SECID

sql.if:
AND ( sdl1.ITEM_VALUE like '%' || #{search} || '%' or sdl2.ITEM_VALUE like '%' || #{search} || '%' OR m.SECID like '%' || #{search} || '%' OR m.CREDIT_TYPE like '%' || #{search} || '%'
or (m.MYIELD*100 = #{search}) or (m.MCPRICE = #{search}) or (m.MINT = #{search}) or (m.M_MDURATION = #{search}) or (m.M_CNVXTY = #{search})
)

mapper.select:
select pm.STATUS status
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


        PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


        pm.status in ('A','U','P')


        and pm.PAGE_ID = #{pageId}


        and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


        and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


        and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc

SELECT DISTINCT id,object,text from ( select FIN.FINPROD_MARKET_ID AS id, FIN.FINPROD_MARKET_ID object, FIN.FINPROD_ABBR AS text FROM FIN_PRODUCT FIN where FINPROD_TYPE2=#{finprodType2}
union all select i.SECID AS id, i.SECID object, i.SECNAME AS text from INTERF_CREDITINFO i ) t
AND (t.id like concat('%',concat(#{search},'%')) OR t.text like concat('%',concat(#{search},'%')))
